mapper.select:
SELECT * FROM ( SELECT TB.* FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.MSG_SEQ DESC) AS RNUM, A.MSG_SEQ AS "msgSeq", A.XML_PROCESS_NAME AS "xmlProcessName", C.PROCESS_REMARK AS "processRemark", A.SEND_RESULT AS "sendResult", A.SEND_REGDATE AS "sendRegDate", B.DID_NM AS "didNm", D.GROUP_NM AS "groupNm" , A.DID_PLAYTIME AS "didPlayTime" , A.DID_MACADDRESS AS "didMacAddress", B.DID_IPADDR AS "didIpAddr", A.ERROR_MESSAGE AS "errorMessage" FROM TB_MESSAGEHISTORY A INNER JOIN TB_DIDINFO B ON A.DID_ID = B.DID_ID INNER JOIN TB_SENDMESSAGETYPR C ON A.XML_PROCESS_NAME = C.XML_PROCESS_NAME INNER JOIN TB_GROUPDID E ON A.DID_ID = E.DID_ID INNER JOIN TB_GROUP D ON D.GROUP_CODE = E.GROUP_CODE WHERE 1=1
AND C.XML_PROCESS_NAME LIKE '%' || #{searchKeyword} || '%'
AND A.DID_ID LIKE '%' || #{searchKeyword} || '%'
AND B.DID_MODELTYPE = 'DIDRMODELTYPE03'
AND B.ROLE_CODE IN ( SELECT GROUP_ID FROM LETTNAUTHORGROUPINFO WHERE PARENT_GROUP_ID = #{groupCode} )
AND B.ROLE_CODE = #{groupCode}
AND A.DID_ID = #{didId}
AND A.MSG_SEQ = #{msgSeq}
AND A.XML_PROCESS_NAME = #{xmlProcessName}
AND TO_CHAR(A.SEND_REGDATE, 'YYYYMMDD') BETWEEN #{schStartDay} AND #{schEndDay}
AND B.CENTER_ID = #{centerId}
) TB ) TA WHERE RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

		SELECT
			COALESCE(COUNT(*),0)
        FROM TB_MESSAGEHISTORY A
        INNER JOIN TB_DIDINFO B  ON A.DID_ID = B.DID_ID
        INNER JOIN TB_SENDMESSAGETYPR C  ON A.XML_PROCESS_NAME = C.XML_PROCESS_NAME
        INNER JOIN TB_GROUPDID E  ON A.DID_ID = E.DID_ID
        INNER JOIN TB_GROUP D  ON D.GROUP_CODE = E.GROUP_CODE
        WHERE 1=1



					AND C.XML_PROCESS_NAME LIKE '%' || #{searchKeyword} || '%'


					AND A.DID_ID LIKE '%' || #{searchKeyword} || '%'





				AND B.DID_MODELTYPE = 'DIDRMODELTYPE03'


				AND B.ROLE_CODE IN
				(
					SELECT GROUP_ID
					FROM LETTNAUTHORGROUPINFO
					WHERE PARENT_GROUP_ID = #{groupCode}
				)


				AND B.ROLE_CODE = #{groupCode}



			AND A.DID_ID = #{didId}


			AND A.MSG_SEQ = #{msgSeq}


			AND A.XML_PROCESS_NAME = #{xmlProcessName}


			AND TO_CHAR(A.SEND_REGDATE, 'YYYYMMDD') BETWEEN #{schStartDay} AND #{schEndDay}


			AND B.CENTER_ID = #{centerId}

		SELECT COALESCE(COUNT(*),0)
		FROM TB_DIDSENDMESSAGE A
        INNER JOIN  TB_DIDINFO B ON A.DID_ID = B.DID_ID
		WHERE A.SEND_DIDCHECKDATE IS NULL
		AND A.DID_ID = #{didId}
		AND B.DID_MAC= #{didMacAddress}

SELECT COALESCE(COUNT(*),0)
FROM TB_MESSAGEHISTORY
WHERE SEND_DIDID = #{sendDidId}

mapper.insert:
		INSERT INTO TB_MESSAGEHISTORY
		(
			MSG_SEQ, DID_ID, XML_PROCESS_NAME, SEND_RESULT, SEND_REGDATE,
			DID_MACADDRESS, ERROR_MESSAGE
		)
		VALUES
		(
            NEXTVAL('msg_seq'), #{didId}, #{xmlProcessName}, #{sendResult}, NOW(),
			#{didMacAddress}, #{errorMessage, jdbcType=VARCHAR}
		)
